$explanations = @{
    1 = "বালুচর কাজী নজরুল ইসলামের রচনা নয়। এটি তার 'মৃত্যুক্ষুধা' ও 'বাঁধনহারা' উপন্যাসের চরিত্রবহির্ভূত একটি গ্রন্থ। ছায়ানট, চক্রবাক ও রুদ্রমঙ্গল তারই রচনা।"
    2 = "সবুজপত্র পত্রিকাটি ১৯১৪ সালে প্রকাশিত হয়। এটি বাংলা সাহিত্যের আধুনিক যুগের সূচনাকারী পত্রিকা হিসেবে পরিচিত এবং এর সম্পাদক ছিলেন কাজী নজরুল ইসলাম নয়, বরং অক্ষয়চন্দ্র সরকার।"
    3 = "পায়ের আওয়াজ পাওয়া যায় সৈয়দ শামসুল হকের রচিত একটি মুক্তিযুদ্ধভিত্তিক নাটক। নূরলদীনের সারা জীবন সৈয়দ শামসুল হকের আরেকটি নাটক হলেও এটি মুক্তিযুদ্ধভিত্তিক নয়।"
    4 = "বেদের মেয়ে জসীমউদ্দীনের রচিত একটি নাটক। রাখালী তার কাব্যগ্রন্থ, মাটির কান্না উপন্যাস এবং বোবা কাহিনী আরেকটি কাব্যগ্রন্থ।"
    5 = "মধ্যযুগের বাংলা সাহিত্যে শ্রীচৈতন্যদেবের প্রভাব অপরিসীম। তার বৈষ্ণব আন্দোলন বাংলা সাহিত্যে পদাবলী, শ্রীচৈতন্যচরিত ইত্যাদি ধারার বিকাশ ঘটায়।"
