    15 = "চার ইয়ারী কথা ভ্রমণসাহিত্য বিষয়ক গ্রন্থ নয়। এটি সৈয়দ হামজার লেখা একটি উপন্যাস। পালামৌ, দৃষ্টিপাত ও দেশে বিদেশে ভ্রমণসাহিত্য।"
    16 = "সীতারাম উপন্যাসে গ্রামীণ সমাজ জীবনের চিত্র প্রাধান্য লাভ করেনি। বঙ্কিমচন্দ্রের এই উপন্যাসের মূল বিষয় ধর্ম ও রাজনীতি।"
    17 = "ঘরে বাইরে উপন্যাসের প্রধান চরিত্র নিখিলেস ও বিমলা। রবীন্দ্রনাথ ঠাকুরের এই উপন্যাসে স্বদেশী আন্দোলনের প্রেক্ষাপটে বিবাহিত জীবনের জটিলতা চিত্রিত হয়েছে।"
    18 = "কুহেলিকা কাজী নজরুল ইসলামের রচিত একটি উপন্যাস। তার অন্যান্য উপন্যাসের মধ্যে মৃত্যুক্ষুধা ও বাঁধনহারা উল্লেখযোগ্য।"
    19 = "বীরাঙ্গনা মাইকেল মধুসূদন দত্তের পত্রকাব্য। এটি ১২টি পত্রের সমষ্টি যেখানে বিভিন্ন ঐতিহাসিক নায়িকার বক্তব্য স্থান পেয়েছে।"
    20 = "একখানি ছোট ক্ষেত আমি একেলা রবীন্দ্রনাথ ঠাকুরের সোনার তরী কবিতার চরণ। এটি তার সোনার তরী কাব্যগ্রন্থের অন্তর্ভুক্ত।"
