    30 = "মিথ্যাবাদীকে সবাই অপছন্দ করে বাক্যটির নেতিবাচক রূপঃ মিথ্যাবাদীকে কেউ পছন্দ করে না। অপছন্দ-এর বিপরীত পছন্দ এবং সবাই-এর বিপরীত কেউ না।"
    31 = "Null and Void-এর বাংলা পরিভাষা বাতিল। আইনগত ভাষায় Null and Void বলতে সম্পূর্ণ অকার্যকর ও বাতিল বুঝায়।"
    32 = "হেড মৌলভী শব্দটি ইংরেজি (Head) ও ফার্সি (মৌলভী) ভাষার শব্দ যোগে গঠিত হয়েছে। মৌলভী একটি ফার্সি শব্দ।"
    33 = "রবীন্দ্র শব্দের সঠিক সন্ধি বিচ্ছেদ রবি + ইন্দ্র। রবি (সূর্য) ও ইন্দ্র (দেবরাজ) এর সমন্বয়ে রবীন্দ্র শব্দ গঠিত।"
    34 = "চেনা এখানে বিশেষণ পদ। 'এ যে আমাদের চেনা লোক' বাক্যে 'চেনা' বিশেষণ হিসেবে 'লোক' শব্দটিকে বিশেষিত করেছে।"
    35 = "প্রকর্ষ শব্দের সমার্থক শব্দ উৎকর্ষ। প্রকর্ষ অর্থ উন্নতি বা শ্রেষ্ঠত্ব, যার সমার্থক হলো উৎকর্ষ।"
    36 = "Professor Razzak was a scholar of refute. 'Scholar of' একটি নির্দিষ্ট prepositional phrase যা কোনো বিষয়ে পণ্ডিত ব্যক্তিকে বোঝায়।"
    37 = "John Smith is good at Mathematics. 'Good at' একটি নির্দিষ্ট prepositional phrase যা কোনো বিষয়ে দক্ষতা বোঝাতে ব্যবহৃত হয়।"
    38 = "Teacher said, 'The earth moves round the sun.' Universal truth বা চিরন্তন সত্যের ক্ষেত্রে Present Indefinite Tense ব্যবহৃত হয়।"
    39 = "Syntax deals with formation of sentences. বাক্য গঠন সংক্রান্ত ব্যাকরণের শাখাকে Syntax বা বিন্যাস বলা হয়।"
    40 = "He insisted on my going there. 'Insist on' preposition-এর পর gerund (verb+ing) ব্যবহৃত হয়।"
    41 = "A stitch in time saves nine-এর অর্থ timely action। প্রবাদটির অর্থ হলো সময়মত একটু সতর্কতা বড় ক্ষতি থেকে রক্ষা করে।"
    42 = "'Initiative'-এর antonym হলো apathy। Initiative অর্থ উদ্যোগ/সক্রিয়তা, যার বিপরীত হলো apathy (উদাসীনতা/নিষ্ক্রিয়তা)।"
    43 = "This could have worked if I had been more cautious. Third conditional-এ 'if' অংশে Past Perfect Tense (had + V3) ব্যবহৃত হয়।"
    44 = "I have been living in Dhaka since 2000. 'Since' একটি নির্দিষ্ট সময় বিন্দু (২০০০) বোঝাতে Present Perfect Continuous Tense-এর সাথে ব্যবহৃত হয়।"
    45 = "'Transitory'-এর antonym হলো permanent। Transitory অর্থ অস্থায়ী/ক্ষণস্থায়ী, যার বিপরীত হলো permanent (স্থায়ী)।"
    46 = "Number-এর verb হলো enumerate। Enumerate অর্থ গণনা করা বা সংখ্যা নির্ধারণ করা।"
    47 = "Slow and steady wins the race. 'Slow and steady' একক ধারণা (একটি বিষয়) হওয়ায় singular verb 'wins' ব্যবহার হয়েছে।"
    48 = "Yesterday, he went home. নির্দিষ্ট অতীত সময় (yesterday) উল্লেখ থাকলে Past Indefinite Tense ব্যবহৃত হয়।"
    49 = "'Venerate' অর্থ respect। Venerate মানে অত্যন্ত শ্রদ্ধা বা সম্মান করা।"
    50 = "Credit tk 5000 to my account. 'Credit to' হলো সঠিক prepositional phrase যা অ্যাকাউন্টে জমা দেওয়া বোঝায়।"
    51 = "'To do away with' means to get rid of. অর্থাৎ কোনো কিছু থেকে মুক্তি পাওয়া বা পরিত্রাণ লাভ করা।"
    52 = "Paper is made from wood. কাঁচামালের মূল উপাদানের পরিবর্তন ঘটলে 'made from' ব্যবহৃত হয়, আর গঠনগত পরিবর্তন না হলে 'made of'।"
    53 = "David Copperfield is a Victorian novel. চার্লস ডিকেন্সের এই উপন্যাসটি ভিক্টোরিয়ান যুগের (১৮৩৭-১৯০১) শ্রেষ্ঠ সাহিত্যকর্মগুলোর একটি।"
    54 = "Elegy Written in a Country Churchyard টমাস গ্রে রচনা করেন। এটি ইংরেজি সাহিত্যের একটি বিখ্যাত শোকগাথা।"
    55 = "Measure for Measure একটি সফল comedy। শেক্সপিয়ারের এই নাটকটি কমেডি হিসেবে শ্রেণীবদ্ধ হলেও এতে কিছু ট্র্যাজিক উপাদান রয়েছে।"
    56 = "Romantic age-এর সূচনা Lyrical Ballads-এর Preface প্রকাশনার মাধ্যমে। উইলিয়াম ওয়ার্ডসওয়ার্থ এই Preface-এ রোমান্টিক কবিতার নীতিমালা ব্যাখ্যা করেন।"
    57 = "The Return of the Native টমাস হার্ডি রচনা করেন। এটি তার ওয়েসেক্স উপন্যাসগুলোর অন্যতম।"
    58 = "'Frailty thy name is woman' উইলিয়াম শেক্সপিয়ারের Hamlet নাটকের বিখ্যাত সংলাপ। Hamlet প্রথম অঙ্কে এই উক্তি করে।"
    59 = "The Solitary Reaper কবিতাটি উইলিয়াম ওয়ার্ডসওয়ার্থ রচনা করেন। এটি রোমান্টিক যুগের একটি বিখ্যাত প্রকৃতিকবিতা।"
    60 = "The Merchant of Venice একটি ইহুদি (a Jew) সম্পর্কে শেক্সপিয়ারের নাটক। নাটকের প্রধান চরিত্র Shylock একজন ইহুদি মহাজন।"
    61 = "Candida নাটকটি জর্জ বার্নার্ড শ' রচনা করেন। এটি তার বিখ্যাত নাটকগুলোর একটি যেখানে ভিক্টোরিয়ান সমাজের চিত্রায়ণ হয়েছে।"
    62 = "S.T. Coleridge ইংরেজি সাহিত্যের রোমান্টিক যুগের কবি। রোমান্টিক যুগের অন্যান্য কবি হলেন ওয়ার্ডসওয়ার্থ, ব্লেক, শেলি, কিটস।"
    63 = "Climax of a plot happens at the height। নাটকীয় কাঠামোর চরম বিন্দু বা সংকটমুহূর্তকে climax বলা হয়।"
    64 = "চার্লস ডিকেন্সের রচনায় লন্ডন শহরকে জীবন্ত সত্তা হিসেবে চিত্রিত করা হয়েছে। তার উপন্যাসগুলোতে লন্ডনের বিভিন্ন স্তরের মানুষের জীবন ফুটে উঠেছে।"
    65 = "'Child is the father of man' উইলিয়াম ওয়ার্ডসওয়ার্থের 'My Heart Leaps Up' কবিতা থেকে নেওয়া। অর্থাৎ শিশুর মধ্যেই ভবিষ্যৎ মানুষের গুণাবলি নিহিত।"
    66 = "'Man is a political animal' এরিস্টটল বলেছেন। তিনি তাঁর 'Politics' গ্রন্থে মানুষকে স্বভাবতই রাজনৈতিক জীব বলে অভিহিত করেন।"
    67 = "William Wordsworth ইংরেজি সাহিত্যে 'poet of nature' নামে পরিচিত। প্রকৃতির বিভিন্ন রূপ তার কবিতার প্রধান বিষয়।"
    68 = "A Passage to India ই.এম. ফরস্টার রচনা করেন। এটি ব্রিটিশ ভারতের পটভূমিতে রচিত একটি বিখ্যাত উপন্যাস।"
    69 = "গীতাঞ্জলির ইংরেজি অনুবাদ করেন ডব্লিউ. বি. ইয়েটস। তিনি এর ভূমিকা রচনা করেন এবং ১৯১৩ সালে রবীন্দ্রনাথ নোবেল পুরস্কার লাভ করেন।"
    70 = "ডব্লিউ. বি. ইয়েটস একজন কবি ও নাট্যকার, উপন্যাসিক নন। তিনি আইরিশ সাহিত্যের নোবেল বিজয়ী কবি।"
    71 = "বাঙালী জাতির প্রধান অংশ অস্ট্রিক মূল জাতিগোষ্ঠীর অন্তর্ভুক্ত। অস্ট্রিকরা ছিল বাংলার আদি অধিবাসী এবং তাদের ভাষার প্রভাব বাংলায় বিদ্যমান।"
    72 = "বাংলার সর্বপ্রাচীন জনপদ পুণ্ড্র। পুণ্ড্রবর্ধন (বর্তমান বগুড়া) ছিল প্রাচীন বাংলার প্রথম জনপদ।"
    73 = "বাংলা (দেশ ও ভাষা) নামের উৎপত্তি আইন-ই-আকবরী গ্রন্থে সর্বাধিক উল্লেখিত হয়েছে। এই গ্রন্থে বাংলার বিভিন্ন অঞ্চলের বিবরণ রয়েছে।"
    74 = "ঢাকার লালবাগের দুর্গ শায়েস্তা খান নির্মাণ করেন। এটি ১৬৭৮ সালে নির্মিত হয় এবং এটি অসমাপ্ত কেল্লা নামেও পরিচিত।"
    75 = "বাংলার ছিয়াত্তরের মন্বন্তর ১৭৭০ খ্রিস্টাব্দে ঘটে। এটি বাংলার ইতিহাসের ভয়াবহ দুর্ভিক্ষ যাতে লক্ষ লক্ষ মানুষ প্রাণ হারায়।"
    76 = "সর্বদলীয় কেন্দ্রীয় রাষ্ট্রভাষা সংগ্রাম পরিষদ ৩১ জানুয়ারি ১৯৫২ সালে গঠিত হয়। এটি ভাষা আন্দোলনের সমন্বয় ও পরিচালনার জন্য গঠিত হয়।"
    77 = "৬ দফা দাবি ১৯৬৬ সালে পেশ করা হয়। বঙ্গবন্ধু শেখ মুজিবুর রহমান ১৯৬৬ সালের ৫-৬ ফেব্রুয়ারি লাহোরে এই ৬ দফা দাবি পেশ করেন।"
    78 = "৭ মার্চ ১৯৭১-এর ভাষণের সময় পূর্ব পাকিস্তানে অসহযোগ আন্দোলন চলছিল। বঙ্গবন্ধুর ভাষণের পরই স্বাধীনতা সংগ্রাম শুরু হয়।"
    79 = "২৬ মার্চ, ১৯৭১-এর স্বাধীনতা ঘোষণা বঙ্গবন্ধু ওয়্যারলেসের মাধ্যমে জারী করেন। এটি ইপিআরের ওয়্যারলেস সেট থেকে প্রচারিত হয়।"
    80 = "বাংলাদেশে রোপা আমন ধান অগ্রহায়ণ-পৌষ মাসে কাটা হয়। রোপা আমন সাধারণত জুন-জুলাই মাসে রোপণ করা হয় এবং ডিসেম্বর-জানুয়ারি মাসে কাটা হয়।"
    81 = "সুন্দরবনের ৬২% বাংলাদেশের ভৌগোলিক সীমার মধ্যে পড়েছে। বাকি ৩৮% ভারতের পশ্চিমবঙ্গে অবস্থিত।"
    82 = "MDG-এর অন্যতম লক্ষ্য ছিল ক্ষুধা ও দারিদ্র্য দূর করা। Millennium Development Goals-এর প্রথম লক্ষ্য ছিল চরম দারিদ্র্য ও ক্ষুধা নির্মূল।"
    83 = "তত্ত্বাবধায়ক সরকার ব্যবস্থা সংবিধানের ১৫তম সংশোধনীর মাধ্যমে রদ করা হয়। ২০১১ সালে এই সংশোধনী পাস হয়।"
    84 = "বাংলাদেশের জাতীয় সংসদ এক কক্ষবিশিষ্ট। বাংলাদেশে এককক্ষবিশিষ্ট আইনসভা রয়েছে যার আসন সংখ্যা ৩৫০।"
    85 = "ভারতের ১১১টি ছিটমহল বাংলাদেশের ভৌগোলিক সীমায় অন্তর্ভুক্ত হয়েছে। ২০১৫ সালে ছিটমহল বিনিময় চুক্তির মাধ্যমে এটি কার্যকর হয়।"
    86 = "বাংলাদেশের ভৌগোলিক অবস্থান ৮৮°-০১′ থেকে ৯২°-৪১′ পূর্ব দ্রাঘিমাংশে এবং ২০°-৩৪′ থেকে ২৬°-৩৮′ উত্তর অক্ষাংশে।"
    87 = "বাংলাদেশে প্রথম আদমশুমারি ১৯৭৪ সালে অনুষ্ঠিত হয়। এটি স্বাধীনতার পর প্রথম জনশুমারি ছিল।"
    88 = "পাঙন উপজাতি বা ক্ষুদ্র নৃ-গোষ্ঠীর ধর্ম ইসলাম। এরা মুসলিম ধর্মাবলম্বী এবং বাংলাদেশের বিভিন্ন অঞ্চলে বসবাস করে।"
    89 = "ঢাকার ধোলাই খাল ইসলাম খান খনন করেন। তিনি মুঘল সুবেদার ছিলেন এবং ঢাকাকে রাজধানী হিসেবে গড়ে তোলেন।"
    90 = "এটি ইতিমধ্যেই ব্যাখ্যা আছে।"  # Already has explanation
    91 = "মুক্তিযুদ্ধকালীন ১৪ ডিসেম্বর, ১৯৭১ বুদ্ধিজীবীদের ওপর ব্যাপক হত্যাকাণ্ড সংঘটিত হয়। পাকিস্তান সেনাবাহিনী ও তাদের দোসররা দেশের শ্রেষ্ঠ সন্তানদের হত্যা করে।"
    92 = "বাংলাদেশকে স্বীকৃতি প্রদানকারী প্রথম ইউরোপীয় দেশ পূর্ব জার্মানি। এটি ১৯৭২ সালের ১১ জানুয়ারি বাংলাদেশকে স্বীকৃতি দেয়।"
    93 = "বাংলাদেশের বৃহত্তম জেলা ২০টি। ১৯৮৪ সালে প্রশাসনিক পুনর্বিন্যাসের মাধ্যমে ২০টি জেলাকে বৃহত্তম জেলা হিসেবে বিভক্ত করা হয়।"
    94 = "শুভলং ঝরনা রাঙামাটি জেলায় অবস্থিত। এটি বাংলাদেশের একটি বিখ্যাত পর্যটন কেন্দ্র।"
    95 = "বাংলাদেশের উষ্ণতম স্থান লালপুর, নাটোর। এখানে দেশের সর্বোচ্চ তাপমাত্রা রেকর্ড করা হয়।"
    96 = "বাংলাদেশের জাতীয় পতাকা ১৭ জানুয়ারি, ১৯৭২ সালে গৃহীত হয়। পতাকার সবুজ বৃত্তের মধ্যে লাল সূর্য বাংলাদেশের উদীয়মান স্বাধীনতাকে নির্দেশ করে।"
    97 = "কোনো রাষ্ট্রীয় অনুষ্ঠানে জাতীয় সংগীতের প্রথম ৪টি চরণ বাজানো হয়। 'আমার সোনার বাংলা' গানের প্রথম ৪ লাইন বাজানোর নিয়ম রয়েছে।"
    98 = "ECNEC-এর চেয়ারম্যান বা সভাপতি প্রধানমন্ত্রী। একনেক অর্থ জাতীয় অর্থনৈতিক পরিষদের নির্বাহী কমিটি।"
    99 = "অগ্নিশ্বর কলার উন্নত জাত। এটি বাংলাদেশ কৃষি গবেষণা ইনস্টিটিউট উদ্ভাবিত একটি উচ্চ ফলনশীল কলার জাত।"
    100 = "বর্তমান সময়ে বাংলাদেশ সরকারের বড় অর্জন যুদ্ধাপরাধীদের বিচার। আন্তর্জাতিক অপরাধ ট্রাইব্যুনালের মাধ্যমে যুদ্ধাপরাধীদের বিচার সম্পন্ন করা হয়।"
    101 = "বাংলাদেশে ১৯৯৮ সাল থেকে বয়স্কভাতা চালু হয়। এটি সামাজিক নিরাপত্তা কর্মসূচির অংশ হিসেবে চালু করা হয়।"
    102 = "কোরিয়া সংকটকে কেন্দ্র করে ১৯৫০ সালে 'শান্তির জন্য ঐক্য প্রস্তাব' জাতিসংঘে পেশ করা হয়। উত্তর কোরিয়ার দক্ষিণ কোরিয়া আক্রমণের প্রেক্ষাপটে এই প্রস্তাব গৃহীত হয়।"
    103 = "সুয়েজ খাল ১৮৬৯ সালে চালু হয়। এটি ভূমধ্যসাগর ও লোহিত সাগরকে সংযুক্ত করেছে এবং মিশরে অবস্থিত।"
    104 = "International Mother Earth day ২২ এপ্রিল পালিত হয়। এটি পৃথিবী ও তার পরিবেশ রক্ষায় সচেতনতা বৃদ্ধির জন্য জাতিসংঘ ঘোষিত দিবস।"
    105 = "প্রেসিডেন্ট উইড্রো উইলসনের 14 points-এ ১৪ নম্বর point-এ জাতিপুঞ্জের সৃষ্টির কথা উল্লেখ করা হয়েছে। প্রথম বিশ্বযুদ্ধ শেষে শান্তি প্রতিষ্ঠায় এই পরিকল্পনা ছিল।"
    106 = "১৭৮৩ সালে ভার্সাইতে ৪টি চুক্তি স্বাক্ষরিত হয়। এই চুক্তিগুলো মার্কিন বিপ্লবী যুদ্ধের সমাপ্তি ঘটায়।"
    107 = "লাওসের সরকারি নাম Laos People's Democratic Republic। এটি দক্ষিণ-পূর্ব এশিয়ার একটি কমিউনিস্ট রাষ্ট্র।"
    108 = "চীন সর্বাধিক রাষ্ট্রের সাথে সীমান্তযুক্ত। চীনের ১৪টি দেশের সাথে স্থল সীমান্ত রয়েছে।"
    109 = "জাতিসংঘ উন্নয়ন কর্মসূচি (UNDP)-এর শীর্ষ পদ প্রশাসক (Administrator)। UNDP জাতিসংঘের উন্নয়ন সংক্রান্ত প্রধান সংস্থা।"
    110 = "Green Climate Fund বিশ্বের দরিদ্র দেশগুলোর জন্য ১০০ বিলিয়ন ডলার মঞ্জুর করেছে। জলবায়ু পরিবর্তন মোকাবেলায় এই তহবিল গঠিত হয়।"
    111 = "যুক্তরাষ্ট্র ২০০২ সালের জুনে এককভাবে ABM চুক্তি থেকে নিজেকে প্রত্যাহার করে। প্রেসিডেন্ট বুশের সময় এই সিদ্ধান্ত নেওয়া হয়।"
    112 = "আরব লীগ ১৯৪৫ সালে প্রতিষ্ঠিত হয়। এর প্রতিষ্ঠাতা সদস্য ছিল মিশর, ইরাক, জর্ডান, লেবানন, সৌদি আরব, সিরিয়া ও ইয়েমেন।"
    113 = "Yalta Conference-এর একটি লক্ষ্য ছিল জাতিসংঘ প্রতিষ্ঠা। ১৯৪৫ সালের এই সম্মেলনে Roosevelt, Churchill ও Stalin অংশ নেন।"
    114 = "এটি ইতিমধ্যেই ব্যাখ্যা আছে।"
    115 = "War and Peace উপন্যাসের রচয়িতা লিও টলস্টয়। এটি বিশ্বসাহিত্যের একটি শ্রেষ্ঠ রুশ উপন্যাস।"
    116 = "আন্তর্জাতিক রেড ক্রস-এর সদর দপ্তর জেনেভায় অবস্থিত। ১৮৬৩ সালে প্রতিষ্ঠিত এই সংস্থার প্রধান কার্যালয় সুইজারল্যান্ডে।"
    117 = "IAEA-এর সদর দপ্তর ভিয়েনায় অবস্থিত। আন্তর্জাতিক পরমাণু শক্তি সংস্থা অস্ট্রিয়ার ভিয়েনায় অবস্থিত।"
    118 = "সার্ক ১৯৮৫ সালে প্রতিষ্ঠিত হয়। দক্ষিণ এশীয় আঞ্চলিক সহযোগিতা সংস্থার উদ্বোধনী সম্মেলন ঢাকায় অনুষ্ঠিত হয়।"
    119 = "জাতিসংঘ ১৯৪৫ সালে প্রতিষ্ঠিত হয়। দ্বিতীয় বিশ্বযুদ্ধের পর ৫১টি দেশ নিয়ে এটি প্রতিষ্ঠিত হয়।"
    120 = "আলেপ্পো শহর সিরিয়ায় অবস্থিত। এটি সিরিয়ার বৃহত্তম শহর ও প্রাচীনতম বসতিগুলোর একটি।"
    121 = "মাদার তেরেসা আলবেনিয়ায় জন্মগ্রহণ করেন। তার প্রকৃত নাম ছিল Anjezë Gonxhe Bojaxhiu এবং তিনি আলবেনীয় বংশোদ্ভূত।"
    122 = "যেসব অণুজীব রোগ সৃষ্টি করে তাদের প্যাথোজেনিক (Pathogenic) বলা হয়। প্যাথোজেন অর্থ রোগসৃষ্টিকারী জীবাণু।"
    123 = "শিশুর মনস্তাত্ত্বিক চাহিদা পূরণে স্বীকৃতি, স্নেহ ও সাফল্য সবকটিই জরুরি। ম্যাসলোর চাহিদার সোপানতত্ত্ব অনুযায়ী শিশুর সুষ্ঠু বিকাশে এগুলো অপরিহার্য।"
    124 = "ট্রিপসিন আমিষ জাতীয় খাদ্য হজমে সাহায্য করে। এটি অগ্ন্যাশয় থেকে নিঃসৃত একটি এনজাইম যা প্রোটিন ভেঙে পেপটাইড ও অ্যামিনো অ্যাসিডে পরিণত করে।"
    125 = "বায়ুমণ্ডলে ০.৮% আর্গন বিদ্যমান। বায়ুমণ্ডলে নাইট্রোজেন ৭৮%, অক্সিজেন ২০.৯৫% এবং আর্গন ০.৮%।"
    126 = "মানুষের রক্তে লোহিত কণিকা প্লীহাতে সঞ্চিত থাকে। প্লীহা রক্তের পুরোনো ও ক্ষতিগ্রস্ত লোহিত কণিকা ধ্বংস করে এবং নতুন কণিকা সঞ্চয় করে।"
    127 = "ডায়নামোর সাহায্যে যান্ত্রিক শক্তিকে বিদ্যুৎ শক্তিতে রূপান্তরিত করা হয়। ডায়নামো যান্ত্রিক শক্তিকে তড়িৎ শক্তিতে রূপান্তর করে।"
    128 = "মস্তিষ্ক স্নায়ুতন্ত্রের অঙ্গ। এটি দেহের সকল কার্যক্রম নিয়ন্ত্রণ করে এবং স্নায়ুতন্ত্রের প্রধান অংশ।"
    129 = "নিউমোনিয়া ভাইরাসজনিত রোগ নয়। এটি ব্যাকটেরিয়া বা ফাঙ্গাস দ্বারা সৃষ্ট ফুসফুসের সংক্রমণ। জন্ডিস, এইডস ও চোখ ওঠা ভাইরাসজনিত রোগ।"
    130 = "প্রাণিজগতের উৎপত্তি ও বংশসম্বন্ধীয় বিদ্যাকে জেনেটিক্স (Genetics) বলে। জিনতত্ত্ব বংশগতি ও বিবর্তন বিষয়ক বিজ্ঞান।"
    131 = "ডিজেল পোড়ালে সালফার ডাই-অক্সাইড বাতাসে আসে। ডিজেলে সালফারের পরিমাণ বেশি থাকায় এটি দহনের সময় সালফার ডাই-অক্সাইড উৎপন্ন করে।"
    132 = "মোবাইল টেলিফোনের লাইনের মধ্য দিয়ে তড়িৎশক্তি প্রবাহিত হয়। মোবাইল ফোন তড়িৎ চুম্বকীয় তরঙ্গের মাধ্যমে যোগাযোগ করে।"
    133 = "জীবজগতের জন্য সবচেয়ে ক্ষতিকর রশ্মি গামা রশ্মি। এর অত্যন্ত উচ্চ ভেদন ক্ষমতা ও আয়নীকরণ ক্ষমতার কারণে এটি জীবকোষের জন্য সবচেয়ে ক্ষতিকর।"
    134 = "লাল রং বেশি দূর থেকে দেখা যায়। লাল রঙের তরঙ্গদৈর্ঘ্য সবচেয়ে বেশি (৬২০-৭৫০ nm) হওয়ায় এটি দূর থেকে সহজে দৃশ্যমান হয়।"
    135 = "ক্যান্সার চিকিৎসায় ব্যবহৃত গামা বিকিরণের উৎস আইসোটোপ। যেমন কোবাল্ট-৬০ একটি তেজস্ক্রিয় আইসোটোপ যা গামা রশ্মি নির্গত করে।"
    136 = "ROM Non-volatile মেমোরি। Read Only Memory-তে সংরক্ষিত ডেটা বিদ্যুৎ বন্ধ হলেও মুছে যায় না। SRAM ও DRAM volatile মেমোরি।"
    137 = "Assembly Language 3G Language নয়। এটি একটি 2nd Generation Language যেখানে মেশিন নির্দেশনার পরিবর্তে মেমোনিক কোড ব্যবহার করা হয়।"
    138 = "১ কিলোবাইট = ১০২৪ বাইট সঠিক। কম্পিউটার মেমোরিতে ১ KB = ২^১০ = ১০২৪ বাইট।"
    139 = "Wi-fi IEEE 802.11 স্ট্যান্ডার্ড-এর উপর ভিত্তি করে কাজ করে। এটি ওয়্যারলেস লোকাল এরিয়া নেটওয়ার্কের জন্য একটি আন্তর্জাতিক মান।"
    140 = "TV রিমোর্ট কন্ট্রোলে সাধারণত ইনফ্রারেড ডিভাইস ব্যবহার করা হয়। ইনফ্রারেড রশ্মি রিমোর্ট থেকে টিভিতে সংকেত প্রেরণ করে।"
    141 = "(1011)2 + (0101)2 = (10000)2 যা অপশনে নেই। বাইনারি যোগ: 1011 + 0101 = 10000, তাই সঠিক উত্তর 'কোনোটিই নয়'।"
    142 = "Wi MAX-এর পূর্ণরূপ Worldwide Interoperability for Microwave Access। এটি একটি তারবিহীন যোগাযোগ প্রযুক্তি।"
    143 = "8086 একটি ১৬ বিটের মাইক্রো প্রসেসর। ইন্টেল ১৯৭৮ সালে ১৬-বিটের 8086 মাইক্রোপ্রসেসর উদ্ভাবন করে।"
    144 = "Power Supply Mobile Phone-এর input device নয়। Keypad, Touch Screen ও Camera input device।"
    145 = "Oracle একটি ডাটাবেজ language। এটি একটি রিলেশনাল ডাটাবেস ম্যানেজমেন্ট সিস্টেম (RDBMS)।"
    146 = "লিংকডইন একটি বিজনেস অরিয়েন্টেড সোশ্যাল নেটওয়ার্কিং সার্ভিস, ২০০২ সালে প্রতিষ্ঠিত এবং ২০০৬ সালে সদস্যসংখ্যা ২০ মিলিয়নের অধিক হয়।"
    147 = "গেটওয়ে দুই বা তার অধিক ভিন্ন ধরনের নেটওয়ার্ককে সংযুক্ত করার কাজে ব্যবহৃত হয়। এটি ভিন্ন প্রোটোকলের মধ্যে সংযোগ স্থাপন করে।"
    148 = "RAM কম্পিউটারের প্রাইমারি মেমোরি। প্রাইমারি মেমোরি সরাসরি CPU-এর সাথে যুক্ত এবং এটি দ্রুতগতির ডেটা স্টোরেজ।"
    149 = "Plotter আউটপুট ডিভাইস। এটি বড় আকারের ড্রয়িং বা গ্রাফিক্স প্রিন্ট করার জন্য ব্যবহৃত হয়। এখানে অপশন C-তে 'মেমোরি' ভুলভাবে উল্লেখিত হলেও Plotter মূলত আউটপুট ডিভাইস।"
    150 = "A = {2, 3, 5}, so P(A) এর সদস্য সংখ্যা 2^3 = 8। মৌলিক সংখ্যা x ≤ 5 হলে {2,3,5} এবং পাওয়ার সেটের সদস্য সংখ্যা ২^n = ২^৩ = ৮।"
    151 = "12টি থেকে 5টি বাছাই যেখানে 2টি সর্বদা থাকে = C(10,3) = 120। প্রথমে ২টি পুস্তক fixed, বাকি ১০টি থেকে ৩টি বাছাই = ১০C৩ = ১২০।"
    152 = "সপ্তাহে বুধবার বৃষ্টি না হওয়ার সম্ভাবনা 2/7। ৫ দিন বৃষ্টি, বুধবার বৃষ্টি না হওয়ার মানে ৭ দিনের মধ্যে ২ দিন বৃষ্টি নেই, তাই সম্ভাবনা ২/৭।"
    153 = "৩৫০×৩ = ১০৫০ টাকা, ভ্যাট ১০৫০×৪/১০০ = ৪২ টাকা। ৩ কেজি মিষ্টির মূল্য ১০৫০ টাকা, ৪% হারে ভ্যাট = ৪২ টাকা।"
    154 = "ব্যবহার ২০% কমালে ব্যয় বৃদ্ধি পাবে না। ২৫% মূল্য বৃদ্ধিতে ব্যয় অপরিবর্তিত রাখতে {(২৫×১০০)/(১০০+২৫)} = ২০% ব্যবহার কমাতে হবে।"
    155 = "ল.সা.গু = গুণফল / গ.সা.গু = ৩৩৮০/১৩ = ২৬০। সংখ্যাদ্বয়ের ল.সা.গু. = (গুণফল ÷ গ.সা.গু.) = ৩৩৮০ ÷ ১৩ = ২৬০।"
    156 = "1+3+5+...+(2x-1) = x²। ক্রমিক বিজোড় সংখ্যার যোগফল n², যেখানে n = x, তাই যোগফল x²।"
    157 = "(25)^(2x+3) = 5^(3x+6) বা 5^(4x+6) = 5^(3x+6) ⇒ 4x+6 = 3x+6 ⇒ x=0। উভয়পক্ষের ভিত্তি সমান করে ঘাত তুলনা করে পাই x=0।"
    158 = "বর্গক্ষেত্রের কর্ণ = a√2 = 4√2 ⇒ a = 4, ক্ষেত্রফল = a² = 16। কর্ণের দৈর্ঘ্য √২ গুণ হলে বাহু ৪, ক্ষেত্রফল ১৬ বর্গ একক।"
    159 = "∠C = 180°-(40°+70°) = 70°, ∠B=∠C=70°, তাই সমদ্বিবাহু ত্রিভুজ। দুটি কোণ সমান হওয়ায় ত্রিভুজটি সমদ্বিবাহু।"
    160 = "x-y=3 ⇒ x=y+3, (y+3)²+y²=185 ⇒ 2y²+6y-176=0 ⇒ y=8, x=11। সমীকরণ সমাধান করে পাই x=11, y=8 যা (11,8)।"
    161 = "x-1/x=1 ⇒ (x-1/x)³ = x³-1/x³-3(x-1/x) ⇒ 1 = x³-1/x³-3 ⇒ x³-1/x³ = 4। ঘন সূত্র ব্যবহার করে মান 4 পাওয়া যায়।"
    162 = "একটি সমান্তর ধারা যেখানে n=21, প্রথমপদ 1 ও শেষপদ 81, যোগফল = (21/2)(1+81) = 861। ধারাটির nতম পদ = 4n-3 = 81 ⇒ n=21, যোগফল = ২১/২(১+৮১)=৮৬১।"
    163 = "প্যাটার্ন: 5²+3¹=28, 9²+1¹=810, 2²+1¹=13, then 5²+4¹=25+4=29 নয়। আসলে প্যাটার্ন: 5-3=2, 5+3=8 → 28; 9-1=8, 9+1=10 → 810; 2-1=1, 2+1=3 → 13; 5-4=1, 5+4=9 → 19।"
    164 = "ইংরেজি ১৮তম অক্ষর R, R-এর বামদিকে ১০ম অক্ষর = ১৮-১০ = ৮ম অক্ষর = H। A=১, B=২,..., R=১৮, ১৮-১০=৮ম অক্ষর H।"
    165 = "ধারাটি: ৩×১=৩, ৩×২+১=৭, ৪×১=৪, ৭×২=১৪, ৫×১=৫, ৭×৩=২১, ৬×১=৬, ৭×৪=২৮। ৮ম সংখ্যা ৭×৪=২৮।"
    166 = "দুটি সমান্তরাল রেখা কখনো ছেদ করে না। ইউক্লিডীয় জ্যামিতির স্বীকার্য অনুযায়ী সমান্তরাল রেখা কখনো মিলিত হয় না।"
    167 = "OTTO শব্দটি আয়নায় প্রতিফলিত হলে অপরিবর্তিত থাকে কারণ এটি প্যালিনড্রোম (উল্টো ও সোজা একই)। OPT, NOON, SOS প্যালিনড্রোম নয়।"
    168 = "কূসংস্কার সঠিক বানান। 'কু' উপসর্গ ও 'সংস্কার' শব্দের সমন্বয়ে কূসংস্কার গঠিত। অর্থ অমূলক ধারণা বা কুসংস্কার।"
    169 = "সমতল দর্পণে প্রতিবিম্ব আয়নার পেছনে ঠিক তত দূরে দেখা যায় যত দূরে বস্তুটি আছে। তাই ২ ফুট দূরত্বে প্রতিবিম্ব ২ ফুট দূরে দেখা যাবে।"
    170 = "২ এর x% = ৮ ⇒ (x/১০০)×২ = ৮ ⇒ x = ৪০০। ২-এর ৪০০% = (৪০০/১০০)×২ = ৮।"
    171 = "ধারাটিতে ৩, ৯, ২৭, ৮১, ২৪৩ গুণোত্তর ও ১০, ৮, ৬, ৪ সমান্তর ধারা। প্রশ্নবোধক স্থানে ২ বসবে। দুটি ধারা পরপর সাজানো: গুণোত্তর ও সমান্তর।"
    172 = "বাংলাদেশের সাথে ভারতের সীমানা ৪১৫৬ কি.মি। এটি বিশ্বের দীর্ঘতম স্থল সীমানাগুলোর একটি।"
    173 = "মেয়র মোহাম্মদ হানিফ ফ্লাইওভারের দৈর্ঘ্য ১১.৮ কি.মি। এটি ঢাকা শহরের একটি গুরুত্বপূর্ণ উড়ালসড়ক।"
