$count = 0
foreach ($q in $questions) {
    if ($q.explanation -eq $placeholder) {
        $id = $q.id
        if ($explanations.ContainsKey($id)) {
            $q.explanation = $explanations[$id]
            $count++
        }
    }
}

# Convert back to JSON and write
$json = ConvertTo-Json $questions -Depth 10
[System.IO.File]::WriteAllText("public/bcs/bcs_36.json", $json, [System.Text.Encoding]::UTF8)

Write-Host "Total explanations generated: $count"
